            return obj.get(key, default)
        try:
            return obj[key]
        except Exception:
            pass
        try:
            d = obj.__dict__
            if key in d:
                return d[key]
        except Exception:
            pass
        return default

    def sl(x):
        if x is None:
            return []
        return list(x)

    depot = get(instance, "depot", 0)
    n = get(instance, "n", None)
    customers = get(instance, "customers", None)
    demands = get(instance, "demands", None)
    coords = get(instance, "coords", None)
    if coords is None:
        coords = get(instance, "positions", None)
    dist_matrix = get(instance, "distance_matrix", None)
    if dist_matrix is None:
        dist_matrix = get(instance, "dist", None)

    if customers is None:
        if n is not None:
            customers = [i for i in range(n) if i != depot]
        elif isinstance(demands, dict):
            customers = [k for k in demands.keys() if k != depot]
        elif coords is not None:
            customers = [i for i in range(len(coords)) if i != depot]
        elif dist_matrix is not None:
            customers = [i for i in range(len(dist_matrix)) if i != depot]
        else:
            customers = []
    customers = [c for c in sl(customers) if c != depot]

    capacity = get(instance, "capacity", None)
    if capacity is None:
        capacity = get(instance, "vehicle_capacity", None)
    if capacity is None:
        capacity = 10 ** 18

    if isinstance(demands, dict):
        def demand(c):
            return demands.get(c, 0)
    elif isinstance(demands, (list, tuple)):
        def demand(c):
            return demands[c] if 0 <= c < len(demands) else 0
    else:
        def demand(c):
            return 0

    def dist(i, j):
        if dist_matrix is not None:
            return dist_matrix[i][j]
        if coords is not None:
            a = coords[i]
            b = coords[j]
            dx = a[0] - b[0]
            dy = a[1] - b[1]
            return (dx * dx + dy * dy) ** 0.5
        return abs(i - j)

    def route_load(r):
        s = 0
        for x in r:
            s += demand(x)
        return s

    def route_cost(r):
        if not r:
            return 0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        s += dist(r[-1], depot)
        return s

    def insert_delta(r, c, pos):
        a = depot if pos == 0 else r[pos - 1]
        b = depot if pos == len(r) else r[pos]
        return dist(a, c) + dist(c, b) - dist(a, b)

    def best_insertion_in_route(r, c):
        best_pos = 0
        best_d = None
        for pos in range(len(r) + 1):
            d = insert_delta(r, c, pos)
            if best_d is None or d < best_d - 1e-12 or (abs(d - best_d) <= 1e-12 and pos < best_pos):
                best_d = d
                best_pos = pos
        return best_pos, best_d

    def two_opt(r):
        if len(r) < 4:
            return r
        best = r[:]
        best_cost = route_cost(best)
        improved = True
        while improved:
            improved = False
            n2 = len(best)
            for i in range(n2 - 2):
                for j in range(i + 2, n2):
                    cand = best[:i] + best[i:j + 1][::-1] + best[j + 1:]
                    cc = route_cost(cand)
                    if cc < best_cost - 1e-12 or (abs(cc - best_cost) <= 1e-12 and cand < best):
                        best = cand
                        best_cost = cc
                        improved = True
                        break
                if improved:
                    break
        return best

    def relocate_improve(routes):
        improved = True
        while improved:
            improved = False
            route_costs = [route_cost(r) for r in routes]
            route_loads = [route_load(r) for r in routes]
            for i in range(len(routes)):
                r = routes[i]
                if not r:
                    continue
                for a in range(len(r)):
                    c = r[a]
                    dc = demand(c)
                    rem = r[:a] + r[a + 1:]
                    old_cost = route_costs[i]
                    new_cost_i = route_cost(rem)
                    for j in range(len(routes)):
                        if i == j and len(rem) == 0:
                            continue
                        base_load = route_loads[j] if j != i else route_load(rem)
                        if j == i:
                            base_route = rem
                            base_cost = new_cost_i
                        else:
                            base_route = routes[j]
                            base_cost = route_costs[j]
                        if base_load + dc > capacity:
                            continue
                        for pos in range(len(base_route) + 1):
                            if j == i and pos == a:
                                continue
                            d_ins = insert_delta(base_route, c, pos)
                            total_old = old_cost + (route_costs[j] if j != i else old_cost)
                            total_new = new_cost_i + (base_cost + d_ins if j != i else base_cost + d_ins)
                            if j == i:
                                # moving within same route
                                cand = rem[:pos] + [c] + rem[pos:]
                                nc = route_cost(cand)
                                if nc < old_cost - 1e-12 or (abs(nc - old_cost) <= 1e-12 and cand < r):
                                    routes[i] = cand
                                    improved = True
                                    break
                            else:
                                before = old_cost + base_cost
                                after = new_cost_i + (base_cost + d_ins)
                                if after < before - 1e-12:
                                    routes[i] = rem
                                    routes[j] = base_route[:pos] + [c] + base_route[pos:]
                                    improved = True
                                    break
                        if improved:
                            break
                    if improved:
                        break
                if improved:
                    break
        return routes

    def cross_exchange(routes):
        improved = True
        while improved:
            improved = False
            for i in range(len(routes)):
                for j in range(i + 1, len(routes)):
                    r1 = routes[i]
                    r2 = routes[j]
                    l1 = route_load(r1)
                    l2 = route_load(r2)
                    c1 = route_cost(r1)
                    c2 = route_cost(r2)
                    for a in range(len(r1)):
                        x = r1[a]
                        dx = demand(x)
                        for b in range(len(r2)):
                            y = r2[b]
                            dy = demand(y)
                            nl1 = l1 - dx + dy
                            nl2 = l2 - dy + dx
                            if nl1 > capacity or nl2 > capacity:
                                continue
                            nr1 = r1[:a] + [y] + r1[a + 1:]
                            nr2 = r2[:b] + [x] + r2[b + 1:]
                            nc = route_cost(nr1) + route_cost(nr2)
                            if nc < c1 + c2 - 1e-12 or (abs(nc - (c1 + c2)) <= 1e-12 and (nr1, nr2) < (r1, r2)):
                                routes[i], routes[j] = nr1, nr2
                                improved = True
                                break
                        if improved:
                            break
                    if improved:
                        break
                if improved:
                    break
        return routes

    unserved = set(customers)
    routes = []
    if not unserved:
        return []

    seeds = sorted(unserved, key=lambda c: (-demand(c), -dist(depot, c), c))
    while unserved:
        seed = None
        for c in seeds:
            if c in unserved:
                seed = c
                break
        if seed is None:
            seed = min(unserved)
        r = [seed]
        unserved.remove(seed)
        load = demand(seed)
        while True:
            best = None
            best_pos = None
            best_score = None
            # cheapest insertion among all feasible customers
            for c in sorted(unserved, key=lambda x: (demand(x) != 0, -demand(x), dist(depot, x), x)):
                dc = demand(c)
                if load + dc > capacity:
                    continue
                pos, dlt = best_insertion_in_route(r, c)
                score = (dlt, -dc, dist(r[-1], c), c, pos)
                if best_score is None or score < best_score:
                    best_score = score
                    best = c
                    best_pos = pos
            if best is None:
                break
            r.insert(best_pos, best)
            load += demand(best)
            unserved.remove(best)
        routes.append(r)

    # Repair any leftover customers by best insertion
    if unserved:
        for c in sorted(unserved, key=lambda x: (-demand(x), dist(depot, x), x)):
            best_r = None
            best_pos = None
            best_score = None
            for i, r in enumerate(routes):
                if route_load(r) + demand(c) > capacity:
                    continue
                pos, dlt = best_insertion_in_route(r, c)
                score = (dlt, i, pos)
                if best_score is None or score < best_score:
                    best_score = score
                    best_r = i
                    best_pos = pos
            if best_r is None:
                routes.append([c])
            else:
                routes[best_r].insert(best_pos, c)
            unserved.discard(c)

    # Local search
    routes = [two_opt(r) for r in routes]
    routes = relocate_improve(routes)
    routes = cross_exchange(routes)
    routes = [two_opt(r) for r in routes]

    # Final cleanup: remove empties, deterministic order
    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (route_cost(r), len(r), r))
    return routes
